<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\FinanceService;Auth::requirePermission('SETTLEMENT_VIEW_CARRIER');$rows=FinanceService::carrier((int)Auth::user()['id']);$pageTitle='Carrier Settlements';require BASE_PATH.'/app/Views/layout/header.php';?><h1>Carrier settlements</h1><div class="card table-wrap"><table><thead><tr><th>Settlement</th><th>Shipment</th><th>Gross</th><th>Deductions</th><th>Net</th><th>Status</th><th>Payout reference</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['settlement_ref'])?></td><td><?=h($r['shipment_ref'])?></td><td><?=h($r['currency'].' '.$r['gross_amount'])?></td><td><?=h($r['deduction_amount'])?></td><td><?=h($r['net_amount'])?></td><td><span class="status-pill status-<?=h($r['settlement_status'])?>"><?=h(str_replace('_',' ',$r['settlement_status']))?></span></td><td><?=h($r['payout_reference']?:'—')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No settlements.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';?>